document.querySelectorAll('[data-lab="PM01-I1"]').forEach(root=>{const q=n=>root.querySelector('[data-field="'+n+'"]'),z=root.dataset.lang==='zh';function update(){const F=+q('force').value,A=+q('area').value,E=+q('modulus').value,s=F/A,e=s/E,d=100*e; q('strip').setAttribute('width',460*(1+10*e));q('strip').setAttribute('height',30+5*A);q('strip').setAttribute('y',125-(30+5*A)/2);q('result').textContent=z?`拉力 ${F} N；面积 ${A.toFixed(1)} mm²；模量 ${E} MPa。应力为 ${s.toFixed(2)} MPa，应变为 ${(e*100).toFixed(3)}%，100 mm测量段伸长 ${d.toFixed(3)} mm。`:`Force ${F} N; area ${A.toFixed(1)} mm²; modulus ${E} MPa. Stress is ${s.toFixed(2)} MPa, strain ${(e*100).toFixed(3)}%, and the 100 mm gauge section extends by ${d.toFixed(3)} mm.`;}root.querySelectorAll('input').forEach(e=>e.addEventListener('input',update));q('reset').addEventListener('click',()=>{q('force').value=10;q('area').value=2;q('modulus').value=1500;update();});update();});